function dangerPacing(state){
 const recent=state.turns.slice(-3);
 const afterOpening=state.turns.length>=2;
 return {allowNewDanger:state.era==='fantasy'&&state.combat?.status!=='playing'&&afterOpening&&!recent.some(turn=>turn.dangerBeat)};
}
function reviewDanger(result,state){
 const beats=result.dangerBeats??[];
 if(!Array.isArray(beats)||beats.length>1)throw Error('새 위험 연출은 한 번에 하나만 제안할 수 있습니다.');
 if(beats.length===0)return null;
 const {cue,response}=beats[0]||{};
 if(!dangerPacing(state).allowNewDanger)throw Error('지금은 새 위험 연출을 추가할 수 없습니다. 현재 행동과 상황을 이어가세요.');
 if(result.era!=='fantasy'||result.location!==state.location||result.scene==='combat'||result.combat.importance!=='none')
  throw Error('새로운 긴장 장면은 현장에서 경고 신호를 제시하고 대응할 수 있어야 합니다.');
 if(typeof cue!=='string'||cue.trim().length<5||cue.length>120||!result.panels.some(panel=>panel.speaker==='narrator'&&panel.text.includes(cue.trim())))
  throw Error('위험 신호는 현재 서술에서 직접 확인되는 내용이어야 합니다.');
 if(typeof response!=='string'||!result.choices.includes(response)||!/피하|피해|물러|숨|기다|멈추|거리|관찰|살피/.test(response))
  throw Error('새 위험 장면에는 관찰하거나 물러나는 선택을 포함해 주세요.');
 return {cue:cue.trim(),response};
}
