function encounterContext(state){
 const level=Math.max(1,state.player?.level||1);
 const party=(state.party||[]).filter(id=>state.present.includes(id)).length;
 const place=G.records.find(p=>p.id===state.location);
 return {
  suggestedStars:Math.min(10,1+Math.floor((level-1)/5)),
  suggestedCount:Math.min(6,1+party+Math.floor((level-1)/5)),
  terrain:place?.note||null,
  available:Roster.encounterMonsters.map(({id,name,stars})=>{
   const {habitat,profile,ecology}=MonsterCatalog.detail(state,id,{creator:true});
   return {id,name,stars,habitat,habits:profile?.habits||ecology};
  }),
 };
}
function validateMonsterScene(result,state){
 const appearances=result.monsterAppearances??[];
 if(!Array.isArray(appearances)||appearances.length>3)throw Error('몬스터 등장 정보가 잘못되었습니다.');
 const newEnemies=result.combat.importance==='none'?[]:result.combat.monsters;
 const existing=state.combat?.status==='playing'?state.combat.monsters:[];
 const seen=new Set();
 for(const {id,panel,evidence} of appearances){
  const narrator=result.panels[panel],quote=typeof evidence==='string'?evidence.trim():'';
  if(result.era!=='fantasy'||!Number.isInteger(panel)||narrator?.speaker!=='narrator'||quote.length<5||quote.length>160||!narrator.text.includes(quote)||!monsterIds.includes(id)||!quote.includes(Roster.get(id).name)||seen.has(id))
   throw Error('몬스터 원화는 현재 장면에서 직접 보이는 등록 몬스터에만 지정할 수 있습니다.');
  seen.add(id);
 }
 if(!existing.length&&new Set([...newEnemies,...seen]).size>6)throw Error('현재 장면의 몬스터 수가 초과되었습니다.');
 result.monsterAppearances=appearances;
}
